var tid = transid;
var flid = tid.split('_')[0];

var droppedAttachmentNames = []

//Parse modifiedInReplyTo

if (typeof modifiedInReplyTo != 'undefined' && modifiedInReplyTo.length > 0) {
    modifiedInReplyTo = '"' + modifiedInReplyTo + '"';
} else {
    modifiedInReplyTo = '""';
}

//Handle Message Body
var messageBody = messagetext;
var messageHTML = messageHTML;
var messageStrippedText = messageStrippedText;
var messageStrippedHTML = messageStrippedHTML;
if (messageHTML === "" || messageHTML == null || messageHTML == undefined) {
    messageHTML = "<p>" + messagetext + "</p>";
}
if (messageHTML === "") {
    messageHTML = messagetext;
}
if (messageBody !== "") {
    messageBody = messagetext;
    messageHTML = messageHTML;
    messageStrippedText = messageStrippedText;
    messageStrippedHTML = messageStrippedHTML;
} else {
    messageBody = "<del>No Content</del>";
    messageHTML = "<del>No Content</del>";
    messageStrippedText = "<del>No Content</del>";
    messageStrippedHTML = "<del>No Content</del>";
}

//Parse PCI Compliance attachment payload For Email

/*

1. create one custom variable with name `emailNonPCIComplianceReasonObject` and assign value `email.pciInfo.nonPCIComplianceReason`
2. create one custom variable with name `emailAttachmentArray` and assign value `email.attachments`

*/

/* Debug below variables( In case of Error):

a. emailNonPCIComplianceReasonObject;
b. emailNonPCIComplianceReasonAttachmentArray;
c. emailAttachmentArray;
d. arr;
e. neededObject;
*/

var logReason = "";
var emailAtt = emailAttachmentArray;
if (emailNonPCIComplianceReasonObject !== null && emailNonPCIComplianceReasonObject !== 'null' && emailNonPCIComplianceReasonObject !== 'NA') {
    var emailNonPCIComplianceReasonObject = JSON.parse(emailNonPCIComplianceReasonObject);
    var emailNonPCIComplianceReasonAttachmentArray = emailNonPCIComplianceReasonObject.attachments;
}
if (emailAttachmentArray !== null && emailAttachmentArray !== '') {
    var emailAttachmentArray = JSON.parse(emailAttachmentArray);
}
var arr = [];
var parseDataAttachment = "";

// Loop only when something is present in Email Attachment Payload

if (emailAttachmentArray.length > 0) {

    // Loop through each element present in Email Attachment Array
    for (var i = 0; i < emailAttachmentArray.length; i++) {

        var emailAttachmentObject = emailAttachmentArray[i];
        var emailAttachmentAttribute_name = emailAttachmentObject.name;
        /*Search file name that is present in Email Attachment throughout
        emailNonPCIComplianceReasonAttachmentArray
        */

        // This determines that some attachments are rejected
        if (emailNonPCIComplianceReasonAttachmentArray.length > 0) {

            for (var j = 0; j < emailNonPCIComplianceReasonAttachmentArray.length; j++) {

                var emailNonPCIComplianceReasonAttachmentObject = emailNonPCIComplianceReasonAttachmentArray[j];

                if (emailAttachmentAttribute_name == emailNonPCIComplianceReasonAttachmentObject.name) {

                    // Assign dropped value to `true`
                    arr[i] = {};

                    arr[i]["mimeType"] = emailNonPCIComplianceReasonAttachmentObject.mimeType;
                    arr[i]["fileName"] = emailNonPCIComplianceReasonAttachmentObject.name;
                    arr[i]["url"] = "";
                    arr[i]["dropped"] = true;

                    break;
                } else {
                    // Assign dropped value to `false`
                    arr[i] = {};
                    arr[i]["mimeType"] = emailAttachmentObject.contentType;
                    arr[i]["fileName"] = emailAttachmentObject.name;
                    arr[i]["url"] = emailAttachmentObject.url;
                    arr[i]["dropped"] = false;
                    continue;
                }
            }
        } else {
            // Determines nothing has been dropped and all accepted
            // End User sent all allowed files
            // Assign dropped value to `false`
            arr[i] = {};
            arr[i]["mimeType"] = emailAttachmentObject.contentType;
            arr[i]["fileName"] = emailAttachmentObject.name;
            arr[i]["url"] = emailAttachmentObject.url;
            arr[i]["dropped"] = false;
        }

        if (isPCIValidationDone == 'NA' && isPCIValidationDone.length > 0) {
            arr[i] = {};
            arr[i]["mimeType"] = emailAttachmentObject.contentType;
            arr[i]["fileName"] = emailAttachmentObject.name;
            arr[i]["url"] = emailAttachmentObject.url;
            arr[i]["dropped"] = false;
        }
    }
} else {

    // If nothing present in Email Attachment Array

}

//`parseDataAttachment` variable can be used as payload
if (arr.length) {
    parseDataAttachment = JSON.stringify(arr);
} else {
    var emptyArray = [];
    parseDataAttachment = JSON.stringify(emptyArray);
}

//resolve conversation
//var resolveConversationTid = transId.split('_')[0];
// Default senderName Assighnment
if (!senderName || senderName.trim() === "") {
    senderName = defaultSenderName;
}
//Default Subject Assighnment
if (!subject || subject.trim() === "") {
    subject = defaultSubject;
}

var messageDetails = "{" +
"\"appId\": \""+ appId + "\"," +
"\"assetType\": \""+ assetType + "\"," +
"\"senderName\": \""+ senderName + "\"," +
"\"recipient\": \""+ bizemailid + "\"," +
"\"businessEmailId\": \""+ bizemailid + "\"," +
"\"customerEmailId\": \""+ customerEmailId + "\"," +
"\"customerName\": \""+ senderName + "\"," +
"\"toAddresses\": "+ JSON.stringify(toAddresses) + "," +
"\"ccRecipients\": "+ JSON.stringify(ccRecipients) + "," +
"\"bccRecipients\": "+ JSON.stringify(bccRecipients) + "," +
"\"subject\": \""+ subject + "\"," +
"\"inReplyTo\": \""+ inReplyTo + "\"," +
"\"headers\": "+ JSON.stringify(headers) + "," +
"\"message\": \""+ messagetext + "\"," +
"\"htmlMessage\": \""+ messageHTML + "\"," +
"\"strippedText\": \""+ strippedText + "\"," +
"\"strippedHtml\": \""+ strippedHtml + "\"," +
"\"attachments\": "+ JSON.stringify(attachments) + "," +
"\"serviceKey\": \""+ serviceKey + "\"," +
"\"timestamp\": \""+ timestamp + "\"" +
"}";

if (securityNonComplianceReasonObject !== null && securityNonComplianceReasonObject !== 'null' && securityNonComplianceReasonObject !== 'NA') {
    var securityNonComplianceReasonJson = JSON.parse(securityNonComplianceReasonObject);
    var securityNonComplianceReasonAttachmentArray = securityNonComplianceReasonJson.attachments;
}

if (attachments !== null && attachments !== '') {
    var attachmentsArray = JSON.parse(attachments);
}

if (attachmentsArray.length > 0 && securityNonComplianceReasonAttachmentArray.length > 0) {
    for (var i = 0; i < securityNonComplianceReasonAttachmentArray.length; i++) {
        droppedAttachmentNames.push(securityNonComplianceReasonAttachmentArray[i].name);
    }
}

var pci = JSON.stringify({
    "isPCICompliant": JSON.parse(isPCICompliance.replace("NA", "true")),
    "isPCIValidationDone": resolveConversationIsPCIValidationDone,
    "nonPCIComplianceReason": resolveConversationNonPCIComplianceReasonObject,
    "droppedAttachmentCount": JSON.parse(droppedAttachmentCount.replace("NA", "0"))
});

var malwareScanDetails = JSON.stringify({
    "isMalwareCompliant": JSON.parse(isMalwareCompliance.replace("NA", "true")),
    "isMalwareValidationDone": isMalwareValidationDone,
    "malwareFailedReason": malwareNonComplianceReasonObject,
    "droppedAttachmentCount": JSON.parse(malwareScanDroppedAttachmentCount.replace("NA", "0"))
});


var securityScanDetails = JSON.stringify({
    "isSecurityCompliant": JSON.parse(isSecurityCompliance.replace("NA", "true")),
    "isSecurityValidationDone": isSecurityValidationDone,
    "securityFailedReason": securityNonComplianceReasonObject,
    "droppedAttachmentCount": JSON.parse(securityScanDroppedAttachmentCount.replace("NA", "0"))
});

var details = "{\"messageDetails\":" + messageDetails +
" , \"pciDetails\": " + pci +
" , \"malwareScanDetails\": " + malwareScanDetails +
" , \"securityScanDetails\": " + securityScanDetails +
"}";

var detailsJson = details;

var exitCode = "noAttachmentsDropped";
var droppedAttachmentNotificationMessage = "";
var securityNonComplianceReasonString = JSON.stringify(securityNonComplianceReasonObject);

if (securityNonComplianceReasonString.indexOf("PCI: Failed:") != -1 ||
    securityNonComplianceReasonString.indexOf("Malware: Failed:") != -1) {
    droppedAttachmentNotificationMessage = sensitiveOrMaliciousContentFoundErrorMessage + droppedAttachmentNames.toString();
    exitCode = "attachmentsDropped";
} else if (securityNonComplianceReasonString.indexOf("System Alert") != -1) {
    droppedAttachmentNotificationMessage = errorProcessingAttachmentsMessage;
    exitCode = "attachmentsDropped";
} else {
    exitCode = "noAttachmentsDropped";
}
exitCode;

